<?php

declare(strict_types=1);

namespace WHMCS\Module\Addon\Uptimeify\Admin;

use WHMCS\Module\Addon\Uptimeify\Bridge;
use WHMCS\Module\Addon\Uptimeify\Container;
use WHMCS\Module\Addon\Uptimeify\Lang;

/**
 * Renders the admin PHP templates (spec §4: no Smarty in the admin) and holds the helpers they use: escaping,
 * translation in the admin language with `%brand%` filled in, and module links.
 *
 * Every dynamic value in a template goes through e(); only `$tokenField` (generated by WHMCS) and `$content` (an
 * already rendered template) are printed raw.
 */
final class View
{
    /** @var array<string,array<string,string>> language => strings */
    private static array $languages = [];

    /** @param array<string,mixed> $vars */
    public static function render(string $template, array $vars): string
    {
        $file = dirname(__DIR__, 2) . '/templates/admin/' . basename($template) . '.php';
        if (!is_file($file)) {
            throw new \RuntimeException('template not found: ' . $template);
        }
        return (static function (string $__file, array $__vars): string {
            extract($__vars, EXTR_SKIP);
            ob_start();
            try {
                include $__file;
            } finally {
                $out = (string) ob_get_clean();
            }
            return $out;
        })($file, $vars);
    }

    public static function e(mixed $value): string
    {
        if (is_bool($value)) {
            $value = $value ? '1' : '0';
        }
        return is_scalar($value) || $value instanceof \Stringable ? htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') : '';
    }

    /**
     * Admin-language text for `$key` (unescaped: pass it through e() when rendering).
     *
     * @param array<string,scalar> $vars
     */
    public static function t(string $key, array $vars = []): string
    {
        $language = Bridge::adminLanguage();
        $strings = self::$languages[$language] ??= Lang::load($language);
        return Lang::t($strings, $key, $vars + ['brand' => Container::settings()->brandName()]);
    }

    /**
     * `$modulelink` plus query parameters (unescaped).
     *
     * @param array<string,scalar> $params
     */
    public static function url(string $modulelink, array $params): string
    {
        return $params === [] ? $modulelink : $modulelink . (str_contains($modulelink, '?') ? '&' : '?') . http_build_query($params);
    }

    /** Hidden inputs that carry the query string of `$url`, for GET forms (a GET form replaces the action's query). */
    public static function hiddenQuery(string $url): string
    {
        parse_str((string) parse_url($url, PHP_URL_QUERY), $query);
        $out = '';
        foreach ($query as $name => $value) {
            if (is_scalar($value)) {
                $out .= '<input type="hidden" name="' . self::e($name) . '" value="' . self::e($value) . '">';
            }
        }
        return $out;
    }

    /** The path part of `$url` (the action of a GET form). */
    public static function path(string $url): string
    {
        return (string) parse_url($url, PHP_URL_PATH);
    }
}
